import { useMemo } from "react";
import { useAuthStore } from "@/stores";
import { hasPermission } from "@/constants/rbac";
import {
  useObligationList,
  useAssignmentList,
  useCAPList,
  useNCCList,
  useRegulationList,
} from "@/hooks/queries";

/** Counts shown on the top-nav tabs/quick-launchers indicating how many items
 * are awaiting the *current user's* action. Defensive on purpose: each
 * computation is isolated in a try/catch, and a missing/loading/erroring
 * query is treated as 0. This is a prototype heuristic — accurate within
 * reason, not a strict reconciliation. */
export interface TabActionCounts {
  regulations: number;
  assignments: number;
  obligations: number;
  caps: number;
  nccs: number;
}

const SAFE_ZERO: TabActionCounts = {
  regulations: 0,
  assignments: 0,
  obligations: 0,
  caps: 0,
  nccs: 0,
};

const isOverdue = (iso: string, completed: boolean) =>
  !completed && new Date(iso).getTime() < Date.now();

export function useTabActionCounts(): TabActionCounts {
  const { user, role } = useAuthStore();
  const userId = user?.id ?? "";

  // Fetch broadly (no server-side role filter; we filter client-side so the
  // single hook covers all roles and so we can include "oversight" counts
  // for executives). A large pageSize is fine — the mock DB is small and the
  // real backend will paginate, so the per-page count is a sensible fallback.
  const obligationsQ = useObligationList({}, 1, 500);
  const assignmentsQ = useAssignmentList({}, 1, 500);
  const capsQ = useCAPList({}, 1, 500);
  const nccsQ = useNCCList({}, 1, 500);
  const regulationsQ = useRegulationList({}, 1, 500);

  return useMemo<TabActionCounts>(() => {
    if (!role) return SAFE_ZERO;
    // Tab visibility — if a role lacks the underlying read permission,
    // expose 0 (the parent component typically also hides the tab itself).
    const canRead = {
      regulation: hasPermission(role, "regulation:read"),
      assignment: hasPermission(role, "assignment:read"),
      obligation: hasPermission(role, "compliance:read"),
      cap: hasPermission(role, "cap:read"),
      ncc: hasPermission(role, "ncc:read"),
    };
    if (
      !canRead.regulation &&
      !canRead.assignment &&
      !canRead.obligation &&
      !canRead.cap &&
      !canRead.ncc
    ) {
      return SAFE_ZERO;
    }

    const result: TabActionCounts = { ...SAFE_ZERO };

    try {
      const assignments = assignmentsQ.data?.items ?? [];
      const obligations = obligationsQ.data?.items ?? [];
      const caps = capsQ.data?.items ?? [];
      const nccs = nccsQ.data?.items ?? [];
      const regulations = regulationsQ.data?.items ?? [];

      // ----- assignments -----
      if (canRead.assignment) {
        if (role === "owner") {
          // Need acknowledgment (status: published) or already assigned to me
          // and still in active work.
          result.assignments = assignments.filter(
            (a) =>
              a.status === "published" ||
              (a.assignorId === userId &&
                ["acknowledged", "in_progress"].includes(a.status)),
          ).length;
        } else if (role === "approver") {
          // Approvers review: published or in_progress awaiting their nod.
          result.assignments = assignments.filter(
            (a) => a.status === "published" || a.status === "in_progress",
          ).length;
        } else if (role === "admin") {
          result.assignments = assignments.filter((a) => a.status === "published")
            .length;
        }
        // executive → 0
      }

      // ----- obligations -----
      if (canRead.obligation) {
        if (role === "owner") {
          result.obligations = obligations.filter((o) => {
            if (o.ownerId !== userId) return false;
            const inFlight = ["draft", "submitted", "returned"].includes(
              o.status,
            );
            return inFlight || isOverdue(o.dueDate, o.status === "completed");
          }).length;
        } else if (role === "approver") {
          result.obligations = obligations.filter((o) =>
            ["review_required", "submitted"].includes(o.status),
          ).length;
        } else if (role === "admin") {
          result.obligations = obligations.filter(
            (o) =>
              ["review_required", "submitted"].includes(o.status) ||
              isOverdue(o.dueDate, o.status === "completed"),
          ).length;
        } else if (role === "executive") {
          result.obligations = obligations.filter((o) =>
            isOverdue(o.dueDate, o.status === "completed"),
          ).length;
        }
      }

      // ----- caps -----
      if (canRead.cap) {
        if (role === "owner") {
          result.caps = caps.filter((c) => {
            if (c.ownerId !== userId) return false;
            const open = c.status === "Open" || c.status === "In Progress";
            return open || isOverdue(c.dueDate, c.status === "Closed");
          }).length;
        } else if (role === "approver") {
          result.caps = caps.filter((c) => c.status === "Pending Approval")
            .length;
        } else if (role === "admin") {
          result.caps = caps.filter(
            (c) =>
              c.status === "Open" ||
              c.status === "Pending Approval" ||
              isOverdue(c.dueDate, c.status === "Closed"),
          ).length;
        } else if (role === "executive") {
          result.caps = caps.filter(
            (c) => isOverdue(c.dueDate, c.status === "Closed"),
          ).length;
        }
      }

      // ----- nccs -----
      if (canRead.ncc) {
        if (role === "owner") {
          result.nccs = nccs.filter(
            (n) =>
              n.status === "Open" &&
              (n.ownerId === userId || isOverdue(n.dueDate, false)),
          ).length;
        } else {
          // approver / admin / executive → oversight: high/critical open NCCs
          result.nccs = nccs.filter(
            (n) =>
              n.status === "Open" &&
              (n.severity === "high" || n.severity === "critical"),
          ).length;
        }
      }

      // ----- regulations -----
      if (canRead.regulation) {
        // Heuristic: regulations are actionable if they have an active
        // assignment (published/acknowledged/in_progress) or a pending-review
        // obligation referencing them. Use a Set to avoid double counting.
        const liveRegs = new Set<string>();
        for (const a of assignments) {
          if (
            ["published", "acknowledged", "in_progress"].includes(a.status) &&
            a.regulationId
          ) {
            liveRegs.add(a.regulationId);
          }
        }
        for (const o of obligations) {
          if (
            ["review_required", "submitted"].includes(o.status) &&
            o.regulationId
          ) {
            liveRegs.add(o.regulationId);
          }
        }
        // Make sure each count is at least "how many effective regulations
        // exist" so the tab is non-zero in fresh demo state. We cap to the
        // size of the active regulation set so the number isn't misleading.
        const effectiveCount = regulations.filter(
          (r) => r.status === "Effective",
        ).length;
        result.regulations = Math.max(liveRegs.size, effectiveCount);
      }
    } catch {
      // Defensive: if any reducer throws, return zeros rather than crash the
      // whole nav render. The counts will repopulate on the next successful
      // query tick.
      return SAFE_ZERO;
    }

    return result;
  }, [
    role,
    userId,
    obligationsQ.data,
    assignmentsQ.data,
    capsQ.data,
    nccsQ.data,
    regulationsQ.data,
  ]);
}

export default useTabActionCounts;

